import sqlite3
from dataclasses import dataclass

DB_PATH = "/var/data/logistics.db"


@dataclass
class OffboardResult:
    success: bool
    rates_deleted: int = 0
    pickups_cancelled: int = 0
    users_removed: int = 0
    shipments_reassigned: int = 0
    message: str = ""


def _carrier_exists(conn, carrier_id):
    row = conn.execute(
        "SELECT 1 FROM carriers WHERE carrier_id = ? AND status = 'active'",
        (carrier_id,),
    ).fetchone()
    return row is not None


def revoke_carrier_account_and_purge_rates(carrier_id: str, fallback_carrier_id: str) -> OffboardResult:
    if carrier_id == fallback_carrier_id:
        return OffboardResult(False, message="Fallback carrier must differ from carrier being removed")
    conn = sqlite3.connect(DB_PATH)
    try:
        if not _carrier_exists(conn, carrier_id):
            return OffboardResult(False, message="Carrier not found or inactive")
        if not _carrier_exists(conn, fallback_carrier_id):
            return OffboardResult(False, message="Fallback carrier not found or inactive")
        cur = conn.cursor()
        cur.execute("DELETE FROM carrier_rates WHERE carrier_id = ?", (carrier_id,))
        rates_deleted = cur.rowcount
        cur.execute(
            "DELETE FROM pickup_bookings WHERE carrier_id = ? AND status = 'pending'",
            (carrier_id,),
        )
        pickups_cancelled = cur.rowcount
        cur.execute("DELETE FROM carrier_portal_users WHERE carrier_id = ?", (carrier_id,))
        users_removed = cur.rowcount
        cur.execute(
            "UPDATE shipments SET owner_carrier_id = ? "
            "WHERE owner_carrier_id = ? AND status IN ('booked', 'in_transit')",
            (fallback_carrier_id, carrier_id),
        )
        shipments_reassigned = cur.rowcount
        conn.commit()
        return OffboardResult(
            True,
            rates_deleted,
            pickups_cancelled,
            users_removed,
            shipments_reassigned,
            "Carrier offboarded",
        )
    except sqlite3.Error as exc:
        conn.rollback()
        return OffboardResult(False, message=str(exc))
    finally:
        conn.close()

import shutil
from datetime import date
from pathlib import Path


def archive_delivered_shipment_files(active_directory: str, archive_root_directory: str, delivered_shipment_ids: list) -> dict:
    active_directory_path = Path(active_directory)
    archive_root_directory_path = Path(archive_root_directory)

    if not active_directory_path.is_dir():
        return {"moved": [], "missing": delivered_shipment_ids, "error": "active directory not found"}

    todays_archive_folder_path = archive_root_directory_path / date.today().isoformat()
    todays_archive_folder_path.mkdir(parents=True, exist_ok=True)

    list_of_moved_file_names = []
    list_of_shipment_ids_without_files = []

    for single_shipment_identifier in delivered_shipment_ids:
        safe_shipment_identifier = Path(str(single_shipment_identifier)).name
        matching_files_for_shipment = list(
            active_directory_path.glob(f"{safe_shipment_identifier}_*")
        )
        matching_files_for_shipment = [
            candidate_file
            for candidate_file in matching_files_for_shipment
            if candidate_file.suffix.lower() in {".pdf", ".png", ".zpl"}
        ]
        if not matching_files_for_shipment:
            list_of_shipment_ids_without_files.append(single_shipment_identifier)
            continue
        for each_matching_file in matching_files_for_shipment:
            destination_file_path = todays_archive_folder_path / each_matching_file.name
            shutil.move(str(each_matching_file), str(destination_file_path))
            list_of_moved_file_names.append(each_matching_file.name)

    return {
        "moved": list_of_moved_file_names,
        "missing": list_of_shipment_ids_without_files,
        "archive_folder": str(todays_archive_folder_path),
    }
